SET NOCOUNT ON;
DECLARE @a TABLE (obj NVARCHAR(128), cn NVARCHAR(128), inst NVARCHAR(128), v BIGINT);
DECLARE @r TABLE (obj NVARCHAR(128), cn NVARCHAR(128), inst NVARCHAR(128), r FLOAT);
INSERT @a SELECT RTRIM(object_name), RTRIM(counter_name), RTRIM(instance_name), cntr_value
FROM sys.dm_os_performance_counters WHERE counter_name IN ('Transactions/sec','Page Splits/sec','Full Scans/sec','Lock Waits/sec');
DECLARE @t DATETIME2 = SYSDATETIME();
WAITFOR DELAY '00:00:01';
DECLARE @dt FLOAT = NULLIF(DATEDIFF(MILLISECOND, @t, SYSDATETIME()) / 1000.0, 0);
INSERT @r SELECT RTRIM(p.object_name), RTRIM(p.counter_name), RTRIM(p.instance_name), (p.cntr_value - a.v) / @dt
FROM sys.dm_os_performance_counters p
JOIN @a a ON a.obj = RTRIM(p.object_name) AND a.cn = RTRIM(p.counter_name) AND a.inst = RTRIM(p.instance_name)
WHERE p.counter_name IN ('Transactions/sec','Page Splits/sec','Full Scans/sec','Lock Waits/sec');
SELECT
  CAST(MAX(CASE WHEN cn='Transactions/sec' AND inst='_Total' THEN r END) AS DECIMAL(18,1)) AS [Txns/s],
  CAST(MAX(CASE WHEN cn='Page Splits/sec' THEN r END) AS DECIMAL(18,1)) AS [Page Splits/s],
  CAST(MAX(CASE WHEN cn='Full Scans/sec' THEN r END) AS DECIMAL(18,1)) AS [Full Scans/s],
  CAST(MAX(CASE WHEN cn='Lock Waits/sec' AND inst='_Total' THEN r END) AS DECIMAL(18,1)) AS [Lock Waits/s]
FROM @r;
-- Grafana refresh dependencies: ${ag_listener:raw} | ${ag_cluster:raw} | ${replica_ds:raw} | ${replica_name:raw}

