SET NOCOUNT ON;
DECLARE @p NVARCHAR(4000) = CONVERT(NVARCHAR(4000), SERVERPROPERTY('ErrorLogFileName'));
DECLARE @sep CHAR(1) = CASE WHEN @p LIKE '%/%' THEN '/' ELSE '\' END;
SET @p = LEFT(@p, LEN(@p) - CHARINDEX(@sep, REVERSE(@p)) + 1) + 'AlwaysOn_health*.xel';
SELECT TOP 40
  DATEADD(MINUTE, DATEDIFF(MINUTE, GETUTCDATE(), GETDATE()), x.ts) AS [Time],
  x.ev AS [Event], x.ag AS [AG], x.rep AS [Replica], x.prev AS [Previous State], x.cur AS [Current State]
FROM (
  SELECT n.e.value('(@name)[1]', 'nvarchar(100)') AS ev,
         n.e.value('(@timestamp)[1]', 'datetime2') AS ts,
         n.e.value('(data[@name="availability_group_name"]/value)[1]', 'nvarchar(256)') AS ag,
         n.e.value('(data[@name="availability_replica_name"]/value)[1]', 'nvarchar(256)') AS rep,
         n.e.value('(data[@name="previous_state"]/text)[1]', 'nvarchar(100)') AS prev,
         n.e.value('(data[@name="current_state"]/text)[1]', 'nvarchar(100)') AS cur
  FROM (SELECT CAST(event_data AS XML) AS d FROM sys.fn_xe_file_target_read_file(@p, NULL, NULL, NULL)) f
  CROSS APPLY f.d.nodes('/event[@name="availability_replica_state_change" or @name="availability_group_lease_expired" or @name="availability_replica_automatic_failover_validation" or @name="availability_replica_manager_state_change"]') n(e)
) x
WHERE x.ag IS NULL OR x.ag = '$ag_cluster'
ORDER BY x.ts DESC;

