DECLARE @r TABLE (obj NVARCHAR(128), cn NVARCHAR(128), inst NVARCHAR(128), r FLOAT);
INSERT @a SELECT RTRIM(object_name), RTRIM(counter_name), RTRIM(instance_name), cntr_value
FROM sys.dm_os_performance_counters WHERE counter_name IN ('SQL Compilations/sec','SQL Re-Compilations/sec');
DECLARE @t DATETIME2 = SYSDATETIME();
WAITFOR DELAY '00:00:01';
DECLARE @dt FLOAT = NULLIF(DATEDIFF(MILLISECOND, @t, SYSDATETIME()) / 1000.0, 0);
INSERT @r SELECT RTRIM(p.object_name), RTRIM(p.counter_name), RTRIM(p.instance_name), (p.cntr_value - a.v) / @dt
FROM sys.dm_os_performance_counters p
JOIN @a a ON a.obj = RTRIM(p.object_name) AND a.cn = RTRIM(p.counter_name) AND a.inst = RTRIM(p.instance_name)
WHERE p.counter_name IN ('SQL Compilations/sec','SQL Re-Compilations/sec');
SELECT
  CAST(MAX(CASE WHEN cn='SQL Compilations/sec' THEN r END) AS DECIMAL(18,1)) AS [Compilations/s],
  CAST(MAX(CASE WHEN cn='SQL Re-Compilations/sec' THEN r END) AS DECIMAL(18,1)) AS [Re-Compilations/s],
  (SELECT CAST(100.0 * SUM(CASE WHEN usecounts > 1 THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0) AS DECIMAL(5,2))
   FROM sys.dm_exec_cached_plans WHERE objtype IN ('Adhoc','Prepared')) AS [Cache Hit %]
FROM @r;
-- Grafana refresh dependencies: ${ag_listener:raw} | ${ag_cluster:raw} | ${replica_ds:raw} | ${replica_name:raw}

SELECT CAST(
    (CAST(SUM(CASE WHEN usecounts>1 THEN 1 ELSE 0 END) AS FLOAT)/NULLIF(COUNT(*),0))*100
    AS DECIMAL(5,2)) AS [Cache Hit %]
FROM sys.dm_exec_cached_plans
WHERE objtype IN ('Adhoc','Prepared');
-- Grafana refresh dependencies: ${ag_listener:raw} | ${ag_cluster:raw} | ${replica_ds:raw} | ${replica_name:raw}

SELECT objtype AS [Type],
    CAST(SUM(size_in_bytes)/1024.0/1024.0 AS DECIMAL(18,2)) AS [Size MB]
