WAITFOR DELAY '00:00:01';
DECLARE @dt FLOAT = NULLIF(DATEDIFF(MILLISECOND, @t, SYSDATETIME()) / 1000.0, 0);
INSERT @r SELECT RTRIM(p.object_name), RTRIM(p.counter_name), RTRIM(p.instance_name), (p.cntr_value - a.v) / @dt
FROM sys.dm_os_performance_counters p
JOIN @a a ON a.obj = RTRIM(p.object_name) AND a.cn = RTRIM(p.counter_name) AND a.inst = RTRIM(p.instance_name)
WHERE p.counter_name IN ('Logins/sec','Logouts/sec','Number of Deadlocks/sec','Errors/sec');
SELECT
  CAST(MAX(CASE WHEN cn='Logins/sec' THEN r END) AS DECIMAL(18,1)) AS [Logins],
  CAST(MAX(CASE WHEN cn='Logouts/sec' THEN r END) AS DECIMAL(18,1)) AS [Logouts],
  (SELECT cntr_value FROM sys.dm_os_performance_counters
   WHERE counter_name='Number of Deadlocks/sec' AND instance_name='_Total') AS [Deadlocks],
  CAST(MAX(CASE WHEN cn='Errors/sec' AND inst='_Total' THEN r END) AS DECIMAL(18,1)) AS [Errors/s]
FROM @r;
